public function byCategory(): array
{
    return Order::with('items')
        ->where('status', 'paid')
        ->get()
        ->flatMap(fn (Order $order) => $order->items)
        ->filter(fn ($item) => $item->quantity > 0)
        ->groupBy('category')
        ->map(fn ($items) => $items->sum(fn ($item) => $item->price * $item->quantity))
        ->sortDesc()
        ->all();
}
